(()=>{
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={token:localStorage.getItem('fenix_token')||'',me:null,chats:[],chat:null,messages:[],section:'chats',theme:localStorage.getItem('fenix_theme')||'light',authMode:'register',authStep:'email',email:'',signupToken:'',search:'',ws:null,reply:null,editing:null,typing:false,resendUntil:0};
const api=async(path,opt={})=>{const h={'Content-Type':'application/json',...(opt.headers||{})};if(state.token)h.Authorization=`Bearer ${state.token}`;const r=await fetch('/api'+path,{...opt,headers:h});let d={};try{d=await r.json()}catch{}if(!r.ok){if(r.status===401){localStorage.removeItem('fenix_token');state.token='';state.me=null;renderAuth()}throw new Error(d.detail||'Ошибка сервера')}return d};
const upload=async(path,file)=>{const f=new FormData();f.append('file',file);const r=await fetch('/api'+path,{method:'POST',headers:state.token?{Authorization:`Bearer ${state.token}`}:{},body:f});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Ошибка загрузки');return d};
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const avatar=(u,size='md')=>u?.avatar?`<img class="avatar ${size}" src="${esc(u.avatar)}" onerror="this.outerHTML='<div class=\"avatar ${size}\">${esc((u?.display_name||u?.title||u?.username||'?').slice(0,1).toUpperCase())}</div>'">`:`<div class="avatar ${size}">${esc((u?.display_name||u?.title||u?.username||'?').slice(0,1).toUpperCase())}</div>`;
const toast=t=>{let x=$('.toast');if(!x){x=document.createElement('div');x.className='toast';document.body.append(x)}x.textContent=t;x.classList.add('show');clearTimeout(x._t);x._t=setTimeout(()=>x.classList.remove('show'),2800)};
function render(){document.body.dataset.theme=state.theme;if(!state.token)renderAuth();else renderApp()}
function renderAuth(){document.body.innerHTML=`<div class="auth-shell"><div class="auth-glow g1"></div><div class="auth-glow g2"></div><div class="auth-layout"><section class="auth-hero"><div class="hero-brand"><span class="logo">✈</span><b>Fenix</b></div><h2>Общайся без ограничений.</h2><p>Быстрый мессенджер для личных чатов, групп, каналов и звонков.</p><div class="hero-features"><span>✓ Сквозной стиль общения</span><span>✓ Фото, видео и файлы</span><span>✓ Группы и каналы</span><span>✓ Аудио и видеозвонки</span></div></section><section class="auth-card"><div class="auth-brand-mobile"><span class="logo">✈</span><b>Fenix Messenger</b></div><div id="auth-body"></div></section></div></div>`;renderAuthBody()}
function renderAuthBody(){const b=$('#auth-body');let html='';if(state.authStep==='email')html=`<div class="auth-progress"><span class="on"></span><span></span><span></span></div><h1>${state.authMode==='register'?'Создать аккаунт':'Войти в Fenix'}</h1><p class="muted">${state.authMode==='register'?'Регистрация проходит по email. Мы отправим одноразовый код.':'Введите email, привязанный к аккаунту.'}</p><label>Email</label><div class="input-wrap"><span>✉</span><input id="email" type="email" autocomplete="email" placeholder="name@example.com" value="${esc(state.email)}"></div><button class="primary wide" id="email-go">Продолжить <span>→</span></button><div class="secure-note">🔒 Код действует 5 минут и не является паролем.</div><div class="auth-switch">${state.authMode==='register'?'Уже есть аккаунт?':'Нет аккаунта?'} <button class="link" id="switch-auth">${state.authMode==='register'?'Войти':'Создать аккаунт'}</button></div>`;
else if(state.authStep==='code')html=`<button class="back" id="auth-back">← Назад</button><div class="auth-progress"><span class="on"></span><span class="on"></span><span></span></div><h1>Подтвердите email</h1><p class="muted">6-значный код отправлен на<br><b>${esc(state.email)}</b></p><input id="code" class="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000"><button class="primary wide" id="code-go">Подтвердить</button><div class="resend-row"><span id="resend-label">Не получили код?</span><button class="link" id="resend">Отправить снова</button></div><div class="code-help">Проверьте «Спам» и убедитесь, что email введён без ошибки.</div>`;
else html=`<button class="back" id="profile-back">← Назад</button><div class="auth-progress"><span class="on"></span><span class="on"></span><span class="on"></span></div><h1>Настройте профиль</h1><p class="muted">Это последний шаг. После него откроется ваш Fenix.</p><div class="onboard-avatar" id="avatar-pick">${avatar({display_name:'?'},'xxl')}<span>＋</span></div><input type="file" id="avatar-file" accept="image/*" hidden><div class="avatar-actions"><button class="secondary" id="avatar-upload">Загрузить фото</button><button class="link" id="avatar-clear">Убрать</button></div><label>Имя</label><input id="display" maxlength="80" placeholder="Например, Fenix" autocomplete="name"><label>Username</label><div class="username-field"><span>@</span><input id="username" minlength="5" maxlength="32" placeholder="fenix_user" autocomplete="username"><span id="username-status"></span></div><small class="muted">Минимум 5 символов: латиница, цифры и _</small><button class="primary wide" id="profile-go">Создать аккаунт</button>`;
b.innerHTML=html;bindAuth();}
function bindAuth(){
$('#switch-auth')?.addEventListener('click',()=>{state.authMode=state.authMode==='register'?'login':'register';state.authStep='email';renderAuthBody()});
$('#auth-back')?.addEventListener('click',()=>{state.authStep='email';renderAuthBody()});$('#profile-back')?.addEventListener('click',()=>{state.authStep='code';renderAuthBody()});
$('#email-go')?.addEventListener('click',requestCode);$('#resend')?.addEventListener('click',requestCode);$('#code-go')?.addEventListener('click',verifyCode);$('#profile-go')?.addEventListener('click',completeProfile);
$('#code')?.addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,6);if(e.target.value.length===6)verifyCode()});
$('#avatar-pick')?.addEventListener('click',()=>$('#avatar-file')?.click());$('#avatar-upload')?.addEventListener('click',()=>$('#avatar-file')?.click());$('#avatar-clear')?.addEventListener('click',()=>{$('#avatar-pick').innerHTML=avatar({display_name:'?'},'xxl')+'<span>＋</span>';state.onboardAvatar=null});
$('#avatar-file')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>8*1024*1024)return toast('Фото максимум 8 МБ');try{const d=await upload('/files/public/avatar',f);state.onboardAvatar=d.url;$('#avatar-pick').innerHTML=avatar({avatar:d.url},'xxl')+'<span>✓</span>';toast('Фото добавлено')}catch(err){toast(err.message)}});
$('#username')?.addEventListener('input',async e=>{const v=e.target.value.trim();const s=$('#username-status');if(v.length<5){s.textContent='';return}if(!/^[a-zA-Z0-9_]+$/.test(v)){s.textContent='✕';s.className='bad';return}try{const d=await api('/users/check-username/'+encodeURIComponent(v));s.textContent=d.available?'✓':'✕';s.className=d.available?'good':'bad'}catch{}});
}
async function requestCode(){if(Date.now()<state.resendUntil)return toast(`Подождите ${Math.ceil((state.resendUntil-Date.now())/1000)} сек.`);const email=$('#email')?.value.trim().toLowerCase()||state.email;if(!/^\S+@\S+\.\S+$/.test(email))return toast('Введите корректный email');state.email=email;try{await api('/auth/email/request',{method:'POST',body:JSON.stringify({email,purpose:state.authMode==='register'?'register':'login'})});state.resendUntil=Date.now()+45000;state.authStep='code';renderAuthBody();toast('Код отправлен на почту');startResendTimer()}catch(e){toast(e.message)}}
function startResendTimer(){const tick=()=>{const x=$('#resend-label'),b=$('#resend');if(!x||!b)return;if(Date.now()<state.resendUntil){const s=Math.ceil((state.resendUntil-Date.now())/1000);x.textContent=`Повторить через ${s} сек.`;b.disabled=true;b.style.opacity=.45;setTimeout(tick,1000)}else{x.textContent='Не получили код?';b.disabled=false;b.style.opacity=1}};tick()}
async function verifyCode(){const code=$('#code')?.value.trim();if(code.length!==6)return toast('Введите 6-значный код');try{const d=await api('/auth/email/verify',{method:'POST',body:JSON.stringify({email:state.email,code,purpose:state.authMode==='register'?'register':'login'})});if(d.status==='authenticated'){state.token=d.access_token;localStorage.setItem('fenix_token',state.token);await boot()}else{state.signupToken=d.signup_token;state.authStep='profile';state.onboardAvatar=null;renderAuthBody()}}catch(e){toast(e.message)}}
async function completeProfile(){const display=$('#display')?.value.trim(),username=$('#username')?.value.trim();if(!display)return toast('Введите имя');if(!/^[a-zA-Z0-9_]{5,32}$/.test(username))return toast('Username: от 5 символов, только латиница, цифры и _');const s=$('#username-status');if(s?.textContent==='✕')return toast('Этот username уже занят');try{const d=await api('/auth/email/complete?signup_token='+encodeURIComponent(state.signupToken),{method:'POST',body:JSON.stringify({username,display_name:display,avatar:state.onboardAvatar||null})});state.token=d.access_token;localStorage.setItem('fenix_token',state.token);await boot()}catch(e){toast(e.message)}}
async function boot(){try{state.me=await api('/auth/me');state.chats=await api('/chats');state.settings=await api('/social/settings');state.theme=state.settings.theme||state.theme;render()}catch(e){localStorage.removeItem('fenix_token');state.token='';renderAuth();toast(e.message)}}
function renderApp(){document.body.dataset.theme=state.theme;document.body.innerHTML=`<div class="app"><aside class="sidebar"><div class="side-top"><button class="icon-btn" id="menu">☰</button><div class="search"><span>⌕</span><input id="global-search" placeholder="Поиск" value="${esc(state.search)}"></div></div><div class="folders"><button class="folder active" data-section="chats">Все</button><button class="folder" data-section="unread">Непрочитанные</button><button class="folder" data-section="groups">Группы</button><button class="folder" data-section="channels">Каналы</button><button class="folder" data-section="saved">Избранное</button></div><div id="chat-list" class="chat-list"></div><div class="profile-mini" id="profile-open">${avatar(state.me)}<div><b>${esc(state.me?.display_name)}</b><small>@${esc(state.me?.username)}</small></div><button class="dots">⋮</button></div></aside><main class="chat-area"><div id="chat-content"></div></main><nav class="mobile-nav"><button data-nav="chats">💬<span>Чаты</span></button><button data-nav="contacts">👥<span>Контакты</span></button><button data-nav="calls">📞<span>Звонки</span></button><button data-nav="settings">⚙️<span>Настройки</span></button></nav><div id="drawer"></div></div>`;bindApp();renderChatList();renderChat()}
function bindApp(){$('#menu').onclick=()=>openDrawer('menu');$('#profile-open').onclick=()=>openDrawer('profile');$('#global-search').oninput=e=>{state.search=e.target.value;renderChatList()};$$('.folder').forEach(b=>b.onclick=()=>{state.section=b.dataset.section;$$('.folder').forEach(x=>x.classList.toggle('active',x===b));renderChatList()});$$('.mobile-nav button').forEach(b=>b.onclick=()=>{const n=b.dataset.nav;if(n==='chats'){state.chat=null;renderChat()}else openDrawer(n==='settings'?'settings':n==='contacts'?'contacts':'calls')})}
function filteredChats(){let a=[...state.chats];if(state.section==='groups')a=a.filter(x=>x.kind==='group');if(state.section==='channels')a=a.filter(x=>x.kind==='channel');if(state.section==='saved')a=a.filter(x=>x.kind==='saved');if(state.search){const q=state.search.toLowerCase();a=a.filter(x=>(x.title||'').toLowerCase().includes(q)||(x.username||'').toLowerCase().includes(q))}return a}
function renderChatList(){const el=$('#chat-list');if(!el)return;const a=filteredChats();el.innerHTML=a.length?a.map(c=>`<button class="chat-row ${state.chat?.id===c.id?'selected':''}" data-id="${c.id}">${avatar(c)}<span class="chat-meta"><b>${esc(c.title)}</b><small>${esc(c.kind==='channel'?'Канал':c.username?'@'+c.username:'Личный чат')}</small></span><span class="chat-time">${c.kind==='saved'?'⭐':''}</span></button>`).join(''):`<div class="empty-list"><div>⌕</div><b>Чатов пока нет</b><small>Найдите человека через меню «Контакты».</small></div>`;$$('.chat-row').forEach(x=>x.onclick=()=>openChat(Number(x.dataset.id)))}
async function openChat(id){try{state.chat=state.chats.find(x=>x.id===id)||null;state.messages=await api(`/chats/${id}/messages?limit=200`);renderChatList();renderChat();connectWS();if(state.messages.length)api(`/social/read/${id}/${state.messages.at(-1).id}`,{method:'POST'}).catch(()=>{})}catch(e){toast(e.message)}}
function renderChat(){const el=$('#chat-content');if(!el)return;if(!state.chat){el.innerHTML=`<div class="empty-chat"><div class="empty-logo">✈</div><h2>Fenix Messenger</h2><p>Выберите чат слева или найдите пользователя в контактах.</p><button class="primary" id="empty-contacts">Найти людей</button></div>`;$('#empty-contacts')?.addEventListener('click',()=>{openDrawer('contacts');setTimeout(bindPeople,50)});return}el.innerHTML=`<header class="chat-header"><div class="chat-head-main">${avatar(state.chat)}<div><b>${esc(state.chat.title)}</b><small>${state.chat.kind==='channel'?'канал':state.chat.kind==='group'?'группа':'в сети'}</small></div></div><div class="chat-head-actions"><button class="icon-btn" id="call-audio">📞</button><button class="icon-btn" id="call-video">▣</button><button class="icon-btn" id="chat-more">⋮</button></div></header><div class="pinned">📌 <span>Закреплённые сообщения</span><b>›</b></div><div class="messages" id="messages">${state.messages.map(messageHTML).join('')}</div><div class="composer-wrap">${state.reply?`<div class="reply-bar"><b>Ответ</b><span>${esc(state.reply.text||'Медиа')}</span><button id="cancel-reply">×</button></div>`:''}<div class="composer"><button class="icon-btn" id="attach">＋</button><textarea id="message-input" rows="1" placeholder="Сообщение...">${esc(state.editing?.text||'')}</textarea><button class="icon-btn" id="emoji">☺</button><button class="send-btn" id="send">${state.editing?'✓':'➤'}</button></div></div>`;bindChat();scrollBottom()}
function messageHTML(m){const mine=m.sender_id===state.me?.id;return `<div class="message ${mine?'mine':''} ${m.deleted?'deleted':''}" data-id="${m.id}"><div class="bubble"><div class="message-author">${mine?'Вы':'Fenix user'}</div><div class="message-text">${m.deleted?'<i>Сообщение удалено</i>':esc(m.text||'')}</div><div class="message-meta">${m.edited?'изменено · ':''}${new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})} ${mine?'✓✓':''}</div></div></div>`}
function bindChat(){const input=$('#message-input');$('#send').onclick=sendMessage;$('#attach').onclick=()=>openDrawer('attach');$('#emoji').onclick=()=>openDrawer('emoji',['😀','😂','😍','🔥','👍','❤️','🤣','😎','🎉','🤝','😭','🥹','💯','👀','🚀','✨','🤔','😡','🥳','💎','😴','🙏']);$('#chat-more').onclick=()=>openDrawer('chat');$('#cancel-reply')?.addEventListener('click',()=>{state.reply=null;renderChat()});$('#call-audio').onclick=()=>startCall('audio');$('#call-video').onclick=()=>startCall('video');input?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});input?.addEventListener('input',()=>{input.style.height='auto';input.style.height=Math.min(input.scrollHeight,130)+'px';saveDraft()});$$('.message').forEach(m=>m.onclick=()=>openDrawer('message',{id:Number(m.dataset.id),mine:m.classList.contains('mine')}))}
async function sendMessage(){const input=$('#message-input');const text=input?.value.trim();if(!text)return;if(state.editing){try{await api(`/chats/${state.chat.id}/messages/${state.editing.id}`,{method:'PATCH',body:JSON.stringify({text})});state.editing=null;state.messages=await api(`/chats/${state.chat.id}/messages?limit=200`);renderChat()}catch(e){toast(e.message)}return}try{const body={text};if(state.reply)body.reply_to_id=state.reply.id;await api(`/chats/${state.chat.id}/messages`,{method:'POST',body:JSON.stringify(body)});state.reply=null;input.value='';state.messages=await api(`/chats/${state.chat.id}/messages?limit=200`);renderChat();api(`/social/drafts/${state.chat.id}`,{method:'PUT',body:JSON.stringify({text:''})}).catch(()=>{})}catch(e){toast(e.message)}}
let draftTimer;function saveDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(()=>{const v=$('#message-input')?.value||'';if(state.chat)api(`/social/drafts/${state.chat.id}`,{method:'PUT',body:JSON.stringify({text:v})}).catch(()=>{})},500)}
function scrollBottom(){const x=$('#messages');if(x)x.scrollTop=x.scrollHeight}
function connectWS(){if(!state.chat||!state.token)return;if(state.ws)try{state.ws.close()}catch{}const proto=location.protocol==='https:'?'wss':'ws';state.ws=new WebSocket(`${proto}://${location.host}/ws/${state.chat.id}?token=${encodeURIComponent(state.token)}`);state.ws.onmessage=e=>{try{const d=JSON.parse(e.data);if(d.type==='message'&&!state.messages.some(x=>x.id===d.message.id)){state.messages.push(d.message);renderChat()}}catch{}}}
function openDrawer(type,data){const d=$('#drawer');if(!d)return;let html='';if(type==='menu')html=`<div class="drawer"><div class="drawer-head">${avatar(state.me)}<div><b>${esc(state.me.display_name)}</b><small>@${esc(state.me.username)} · ID ${esc(state.me.public_code||state.me.id)}</small></div><button id="drawer-close">×</button></div><button class="drawer-item" data-action="profile">👤 Профиль</button><button class="drawer-item" data-action="contacts">👥 Контакты</button><button class="drawer-item" data-action="saved">⭐ Избранное</button><button class="drawer-item" data-action="calls">📞 Звонки</button><button class="drawer-item" data-action="settings">⚙️ Настройки</button><button class="drawer-item" data-action="appearance">🎨 Оформление</button><button class="drawer-item" data-action="devices">💻 Устройства</button><button class="drawer-item danger" data-action="logout">↪ Выйти</button></div>`;
if(type==='profile')html=profileModal();if(type==='settings')html=settingsModal();if(type==='appearance')html=appearanceModal();if(type==='contacts')html=contactsModal();if(type==='calls')html=callsModal();if(type==='devices')html=devicesModal();if(type==='attach')html=attachModal();if(type==='chat')html=chatModal();if(type==='emoji')html=emojiModal(data);if(type==='message')html=messageModal(data);if(type==='edit-profile')html=editProfileModal();
d.innerHTML=`<div class="overlay"></div>${html}`;d.classList.add('open');$('.overlay',d).onclick=closeDrawer;$('#drawer-close',d)?.addEventListener('click',closeDrawer);$$('[data-action]',d).forEach(x=>x.onclick=()=>handleAction(x.dataset.action,x.dataset.id));bindDrawer(type)}
function closeDrawer(){$('#drawer')?.classList.remove('open')}
function profileModal(){return `<div class="modal profile-modal"><div class="modal-head"><h2>Профиль</h2><button id="drawer-close">×</button></div><div class="profile-center">${avatar(state.me,'xxl')}<h2>${esc(state.me.display_name)}</h2><div class="username-line">@${esc(state.me.username)}</div></div><div class="profile-grid"><div><small>ID</small><b>${esc(state.me.public_code||state.me.id)}</b></div><div><small>Email</small><b>${esc(state.me.email||'—')}</b></div></div><div class="bio-box">${esc(state.me.bio||'Добавьте описание профиля')}</div><button class="primary wide" data-action="edit-profile">Изменить профиль</button></div>`}
function editProfileModal(){return `<div class="modal"><div class="modal-head"><h2>Изменить профиль</h2><button id="drawer-close">×</button></div><div class="profile-edit-avatar" id="edit-avatar-pick">${avatar(state.me,'xxl')}<span>＋</span></div><input type="file" id="edit-avatar-file" accept="image/*" hidden><button class="secondary wide" id="edit-avatar-btn">Изменить фото</button><label>Имя</label><input id="edit-name" value="${esc(state.me.display_name)}" maxlength="80"><label>Username</label><input id="edit-username" value="${esc(state.me.username)}" maxlength="32"><label>О себе</label><textarea id="edit-bio" maxlength="500" placeholder="Расскажите о себе">${esc(state.me.bio||'')}</textarea><button class="primary wide" id="save-profile">Сохранить</button></div>`}
function settingsModal(){return `<div class="modal"><div class="modal-head"><h2>Настройки</h2><button id="drawer-close">×</button></div><div class="settings-user">${avatar(state.me)}<div><b>${esc(state.me.display_name)}</b><small>@${esc(state.me.username)}</small></div></div><h3>Аккаунт</h3><button class="setting-row" data-action="edit-profile"><span>👤</span><div>Профиль<small>Имя, username, аватар, описание</small></div><b>›</b></button><h3>Приложение</h3><button class="setting-row" data-action="toggle-theme"><span>🌙</span><div>Тёмная тема<small>${state.theme==='dark'?'Включена':'Выключена'}</small></div><b>›</b></button><button class="setting-row"><span>🔔</span><div>Уведомления<small>Сообщения и звонки</small></div><b>›</b></button><button class="setting-row"><span>🔒</span><div>Конфиденциальность<small>Блокировка и видимость</small></div><b>›</b></button><button class="setting-row" data-action="devices"><span>💻</span><div>Устройства<small>Активные сеансы</small></div><b>›</b></button><h3>О Fenix</h3><div class="about-row"><b>Fenix Messenger 11.0</b><small>Email-авторизация · WebSocket · адаптивный интерфейс</small></div></div>`}
function appearanceModal(){return `<div class="modal"><div class="modal-head"><h2>Оформление</h2><button id="drawer-close">×</button></div><div class="theme-cards"><button data-theme="light" class="${state.theme==='light'?'chosen':''}">☀️<b>Светлая</b><small>Чистый интерфейс</small></button><button data-theme="dark" class="${state.theme==='dark'?'chosen':''}">🌙<b>Тёмная</b><small>Для вечера</small></button></div></div>`}
function contactsModal(){return `<div class="modal wide-modal"><div class="modal-head"><h2>Контакты</h2><button id="drawer-close">×</button></div><div class="contact-search"><input id="people-q" placeholder="Имя, @username или 3/4-значный ID"><button id="people-go">⌕</button></div><div id="people-list" class="people-list"><div class="muted center">Введите минимум 2 символа для поиска</div></div></div>`}
function callsModal(){return `<div class="modal"><div class="modal-head"><h2>Звонки</h2><button id="drawer-close">×</button></div><div class="call-empty">📞<h3>Звонков пока нет</h3><p>Откройте личный чат и нажмите 📞 или ▣.</p></div></div>`}
function devicesModal(){return `<div class="modal"><div class="modal-head"><h2>Устройства</h2><button id="drawer-close">×</button></div><div class="device-row"><span>💻</span><div><b>Текущее устройство</b><small>${navigator.userAgent.includes('Mobile')?'Мобильный браузер':'Desktop браузер'} · ${location.hostname}</small></div><i>Активно</i></div><div class="secure-box">🔐 Сессия защищена JWT. При выходе токен удаляется из браузера.</div></div>`}
function attachModal(){return `<div class="sheet"><div class="sheet-title">Вложение</div><div class="attach-grid"><button id="file-photo">🖼️<span>Фото</span></button><button id="file-video">🎥<span>Видео</span></button><button id="file-any">📎<span>Файл</span></button><button>🎵<span>Музыка</span></button><button>🎤<span>Голосовое</span></button><button>📍<span>Геопозиция</span></button><button>📊<span>Опрос</span></button><button>👤<span>Контакт</span></button></div><input type="file" id="chat-file" hidden><button id="drawer-close" class="sheet-cancel">Отмена</button></div>`}
function chatModal(){return `<div class="sheet"><div class="sheet-title">${esc(state.chat?.title||'Чат')}</div><button class="sheet-item">🔎 Поиск по чату</button><button class="sheet-item">📌 Закреплённые</button><button class="sheet-item">🔔 Уведомления</button><button class="sheet-item">🖼️ Медиа, файлы и ссылки</button><button class="sheet-item">👥 Участники</button><button class="sheet-item">🔗 Ссылка на чат</button><button class="sheet-item danger">🗑️ Очистить историю</button><button id="drawer-close" class="sheet-cancel">Отмена</button></div>`}
function emojiModal(data){return `<div class="emoji-sheet"><div class="emoji-tabs">😀　🧸　GIF</div><div class="emoji-grid">${data.map(e=>`<button>${e}</button>`).join('')}</div><button id="drawer-close" class="sheet-cancel">Закрыть</button></div>`}
function messageModal(data){return `<div class="sheet"><div class="sheet-title">Сообщение</div><button class="sheet-item" data-action="reply" data-id="${data.id}">↩ Ответить</button><button class="sheet-item" data-action="favorite" data-id="${data.id}">⭐ В Избранное</button><button class="sheet-item" data-action="pin" data-id="${data.id}">📌 Закрепить</button><button class="sheet-item" data-action="reaction" data-id="${data.id}">❤️ Реакция</button>${data.mine?`<button class="sheet-item" data-action="edit" data-id="${data.id}">✏️ Изменить</button><button class="sheet-item danger" data-action="delete" data-id="${data.id}">🗑️ Удалить</button>`:''}<button id="drawer-close" class="sheet-cancel">Отмена</button></div>`}
function bindDrawer(type){if(type==='contacts')setTimeout(bindPeople,30);if(type==='emoji')$$('.emoji-grid button').forEach(x=>x.onclick=()=>{const i=$('#message-input');if(i){i.value+=x.textContent;i.focus()}closeDrawer()});if(type==='appearance')$$('[data-theme]').forEach(x=>x.onclick=async()=>{state.theme=x.dataset.theme;localStorage.setItem('fenix_theme',state.theme);await api('/social/settings',{method:'PATCH',body:JSON.stringify({theme:state.theme})}).catch(()=>{});closeDrawer();renderApp()});if(type==='edit-profile'){let avatarUrl=state.me.avatar;$('#edit-avatar-pick')?.addEventListener('click',()=>$('#edit-avatar-file').click());$('#edit-avatar-btn')?.addEventListener('click',()=>$('#edit-avatar-file').click());$('#edit-avatar-file')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{const d=await upload('/files/avatar',f);avatarUrl=d.url;$('#edit-avatar-pick').innerHTML=avatar({avatar:d.url},'xxl')+'<span>✓</span>'}catch(err){toast(err.message)}});$('#save-profile')?.addEventListener('click',async()=>{try{const name=$('#edit-name').value.trim(),username=$('#edit-username').value.trim(),bio=$('#edit-bio').value.trim();if(!name||!/^[a-zA-Z0-9_]{5,32}$/.test(username))return toast('Проверьте имя и username');state.me=await api('/users/me',{method:'PATCH',body:JSON.stringify({display_name:name,username,bio,avatar:avatarUrl||null})});closeDrawer();renderApp();toast('Профиль сохранён')}catch(e){toast(e.message)}})}if(type==='attach'){const i=$('#chat-file');['file-photo','file-video','file-any'].forEach(id=>$('#'+id)?.addEventListener('click',()=>i.click()));i?.addEventListener('change',async()=>{const f=i.files?.[0];if(!f)return;try{const d=await upload('/files/upload',f);await api(`/chats/${state.chat.id}/messages`,{method:'POST',body:JSON.stringify({text:'',media_url:d.url,media_type:d.content_type})});state.messages=await api(`/chats/${state.chat.id}/messages?limit=200`);closeDrawer();renderChat()}catch(e){toast(e.message)}})}}
function bindPeople(){const q=$('#people-q'),go=$('#people-go');if(!q)return;const run=async()=>{const v=q.value.trim();if(v.length<2)return toast('Минимум 2 символа');try{const arr=await api('/social/people?q='+encodeURIComponent(v));$('#people-list').innerHTML=arr.length?arr.map(u=>`<button class="person-row" data-uid="${u.id}">${avatar(u)}<span><b>${esc(u.display_name)}</b><small>@${esc(u.username)} · ID ${esc(u.public_code||u.id)}</small></span><i>›</i></button>`).join(''):'<div class="muted center">Пользователь не найден</div>';$$('.person-row').forEach(x=>x.onclick=async()=>{const c=await api('/chats/private',{method:'POST',body:JSON.stringify({other_user_id:Number(x.dataset.uid)})});if(!state.chats.some(z=>z.id===c.id))state.chats.unshift(c);closeDrawer();openChat(c.id)})}catch(e){toast(e.message)}};go.onclick=run;q.onkeydown=e=>{if(e.key==='Enter')run()}}
async function startCall(kind){if(!state.chat||state.chat.kind!=='private')return toast('Звонки доступны в личных чатах');try{const people=await api('/social/people?q='+encodeURIComponent(state.chat.username||''));const target=people.find(x=>x.username===state.chat.username);if(!target)return toast('Пользователь не найден');const d=await api('/social/calls',{method:'POST',body:JSON.stringify({callee_id:target.id,kind,chat_id:state.chat.id})});toast(kind==='video'?'Видеозвонок создан':'Аудиозвонок создан');openDrawer('calls')}catch(e){toast(e.message)}}
async function handleAction(a,id){try{if(a==='logout'){await api('/auth/logout',{method:'POST'}).catch(()=>{});localStorage.removeItem('fenix_token');state.token='';state.me=null;closeDrawer();render();return}if(a==='toggle-theme'){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('fenix_theme',state.theme);await api('/social/settings',{method:'PATCH',body:JSON.stringify({theme:state.theme})}).catch(()=>{});closeDrawer();renderApp();return}if(a==='profile'){closeDrawer();openDrawer('profile');return}if(a==='settings'){closeDrawer();openDrawer('settings');return}if(a==='appearance'){closeDrawer();openDrawer('appearance');return}if(a==='contacts'){closeDrawer();openDrawer('contacts');return}if(a==='calls'){closeDrawer();openDrawer('calls');return}if(a==='devices'){closeDrawer();openDrawer('devices');return}if(a==='edit-profile'){closeDrawer();openDrawer('edit-profile');return}if(a==='saved'){const c=await api('/chats/saved');if(!state.chats.some(x=>x.id===c.id))state.chats.unshift(c);closeDrawer();openChat(c.id);return}if(a==='reply'){state.reply=state.messages.find(x=>x.id===Number(id));closeDrawer();renderChat();return}if(a==='favorite'){await api(`/extras/favorites/${id}`,{method:'POST'});toast('Добавлено в Избранное');closeDrawer();return}if(a==='pin'){await api(`/chats/${state.chat.id}/messages/${id}/pin`,{method:'POST'});toast('Статус закрепления изменён');closeDrawer();return}if(a==='reaction'){await api(`/chats/${state.chat.id}/messages/${id}/reaction`,{method:'POST',body:JSON.stringify({emoji:'❤️'})});toast('❤️');closeDrawer();return}if(a==='delete'){await api(`/chats/${state.chat.id}/messages/${id}`,{method:'DELETE'});state.messages=await api(`/chats/${state.chat.id}/messages?limit=200`);closeDrawer();renderChat();return}if(a==='edit'){const m=state.messages.find(x=>x.id===Number(id));state.editing=m;closeDrawer();renderChat();$('#message-input')?.focus();return}}catch(e){toast(e.message)}}
render();if(state.token)boot();
})();
